import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"PII Redactor","description":"","frontmatter":{"title":"PII Redactor"},"headers":[],"relativePath":"docs/tools/pii-redactor.md","filePath":"docs/tools/pii-redactor.md","lastUpdated":1793412416000}'),i={name:"docs/tools/pii-redactor.md"};function n(s,e,l,d,c,f){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="pii-redactor" tabindex="-1">PII Redactor <a class="header-anchor" href="#pii-redactor" aria-label="Permalink to &quot;PII Redactor&quot;">​</a></h1><p>The PII Redactor replaces personally identifiable information in a PDF, CSV, Excel, image or plain-text file. Use it to clean a document before exposing it to an untrusted model or any other service, or before saving a sample statement.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>Drag and drop a file onto the tool.</li><li>Click <strong>Auto-detect</strong> to find likely personal information. For a statement, it finds the account owner&#39;s name, address and account numbers; the general options scan more broadly, including images.</li><li>Review and edit the list of rules — add anything missed, remove false positives.</li><li>Click <strong>Redact</strong>, preview the result, then save it.</li></ol><h2 id="different-files-different-handling" tabindex="-1">Different files, different handling <a class="header-anchor" href="#different-files-different-handling" aria-label="Permalink to &quot;Different files, different handling&quot;">​</a></h2><ul><li><strong>PDFs</strong> are changed minimally, so they are subject to the character limitations of the PDF&#39;s own fonts.</li><li><strong>Images</strong> have personal information blacked out rather than replaced.</li><li><strong>CSVs</strong> can be given synthetic data instead of redacted real data: each transaction row is replaced with invented ones. Or redact specific text throughout, as for a PDF.</li><li><strong>Excel files</strong> have every transaction row removed, keeping the headers and any preamble or footer.</li></ul><p>By default, embedded images (a scanned check, say) are also read for matching text. Tick <strong>Skip Images</strong> to redact the text layer only. Redaction settings can be saved and reused.</p>',7)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
